// Static front-end. Reads data/brawlers.json (generated by scripts/sync.mjs)
// and local images from /images. It never calls the Brawl Stars or Brawlify APIs.
(() => {
  const $ = (id) => document.getElementById(id);
  const state = { all: [], q: '', rarity: null, cls: null, unreleased: false, sort: 'newest' };

  const RARITY_ORDER = ['Trophy Road', 'Rare', 'Super Rare', 'Epic', 'Mythic', 'Legendary', 'Ultra Legendary'];

  // Creates an <img> that falls back to a lettered placeholder if the file is missing.
  function img(src, alt, letter) {
    const wrap = document.createDocumentFragment();
    const ph = () => {
      const d = document.createElement('div');
      d.className = 'ph';
      d.textContent = (letter || alt || '?').trim().charAt(0).toUpperCase();
      return d;
    };
    if (!src) { wrap.appendChild(ph()); return wrap; }
    const el = document.createElement('img');
    el.src = src; el.alt = alt; el.loading = 'lazy'; el.decoding = 'async';
    el.addEventListener('error', () => el.replaceWith(ph()), { once: true });
    wrap.appendChild(el);
    return wrap;
  }

  function el(tag, cls, text) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  }

  function matches(b) {
    if (!state.unreleased && !b.released) return false;
    if (state.rarity && b.rarity.name !== state.rarity) return false;
    if (state.cls && b.class !== state.cls) return false;
    const q = state.q.trim().toLowerCase();
    if (!q) return true;
    const hay = [b.name, b.class, b.rarity.name, ...b.starPowers.map((s) => s.name), ...b.gadgets.map((g) => g.name)].join(' ').toLowerCase();
    return hay.includes(q);
  }

  function sorted(list) {
    const s = [...list];
    switch (state.sort) {
      case 'oldest': return s.sort((a, b) => a.id - b.id);
      case 'az': return s.sort((a, b) => a.name.localeCompare(b.name));
      case 'za': return s.sort((a, b) => b.name.localeCompare(a.name));
      default: return s.sort((a, b) => b.id - a.id);
    }
  }

  function render() {
    const list = sorted(state.all.filter(matches));
    const grid = $('grid');
    grid.replaceChildren();
    for (const b of list) {
      const card = el('button', 'card');
      card.type = 'button';
      card.style.setProperty('--rarity', b.rarity.color);
      card.setAttribute('aria-label', `${b.name}, ${b.rarity.name} ${b.class}`);
      const art = el('div', 'art');
      art.appendChild(img(b.image, b.name, b.name));
      card.append(art, el('div', 'name', b.name), el('div', 'meta', `${b.rarity.name} · ${b.class}`));
      if (!b.released) card.appendChild(el('span', 'tag', 'Unreleased'));
      card.addEventListener('click', () => openDetail(b));
      grid.appendChild(card);
    }
    $('count').textContent = `${list.length} brawler${list.length === 1 ? '' : 's'}`;
    $('empty').hidden = list.length > 0;
  }

  function buildChips(containerId, values, key) {
    const box = $(containerId);
    box.replaceChildren();
    const make = (label, value) => {
      const c = el('button', 'chip', label);
      c.type = 'button';
      c.setAttribute('aria-pressed', String(state[key] === value));
      c.addEventListener('click', () => {
        state[key] = value;
        box.querySelectorAll('.chip').forEach((x) => x.setAttribute('aria-pressed', 'false'));
        c.setAttribute('aria-pressed', 'true');
        render();
      });
      box.appendChild(c);
    };
    make('All', null);
    values.forEach((v) => make(v, v));
  }

  function abilityEl(item) {
    const row = el('div', 'ability');
    const icon = el('div', 'icon');
    icon.appendChild(img(item.image, item.name, item.name));
    const text = el('div');
    text.appendChild(el('b', null, item.name));
    const p = el('p');
    // descHtml is sanitised by scripts/sync.mjs (only <br> and <span class="hl"> survive).
    p.innerHTML = item.descHtml || '';
    text.appendChild(p);
    row.append(icon, text);
    return row;
  }

  function openDetail(b) {
    $('d-name').textContent = b.name;
    const portrait = $('d-portrait');
    portrait.replaceChildren(img(b.image, b.name, b.name));
    const badges = $('d-badges');
    badges.replaceChildren();
    const r = el('span', 'badge', b.rarity.name);
    r.style.color = b.rarity.color; r.style.borderColor = b.rarity.color;
    badges.append(r, el('span', 'badge', b.class));
    if (!b.released) badges.appendChild(el('span', 'badge', 'Unreleased'));
    $('d-desc').innerHTML = b.descHtml || '';
    $('d-sp').replaceChildren(...b.starPowers.map(abilityEl));
    $('d-gd').replaceChildren(...b.gadgets.map(abilityEl));
    // Optional sections, only present if the sync found them in the API.
    const extra = $('d-extra');
    extra.replaceChildren();
    for (const [key, title] of [['hypercharges', 'Hypercharges'], ['buffies', 'Buffies'], ['gears', 'Gears']]) {
      if (!b[key]?.length) continue;
      const h = el('h3', null, title);
      const box = el('div', 'abilities');
      box.append(...b[key].map(abilityEl));
      extra.append(h, box);
    }
    if (!$('detail').open) $('detail').showModal();
    history.replaceState(null, '', `#${encodeURIComponent(b.slug || b.name)}`);
  }

  function openFromHash() {
    const key = decodeURIComponent(location.hash.slice(1)).toLowerCase();
    if (!key) return;
    const b = state.all.find((x) => (x.slug || x.name).toLowerCase() === key);
    if (b) { state.unreleased = state.unreleased || !b.released; $('unreleased').checked = state.unreleased; render(); openDetail(b); }
  }

  async function init() {
    let data;
    try {
      const res = await fetch('data/brawlers.json', { cache: 'no-cache' });
      if (!res.ok) throw new Error(res.status);
      data = await res.json();
    } catch {
      $('error').hidden = false;
      return;
    }
    state.all = data.brawlers || [];
    $('sample-banner').hidden = !data.sample;
    if (data.generatedAt) {
      $('stamp').textContent = `Data updated ${new Date(data.generatedAt).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' })} · ${state.all.length} brawlers`;
    }

    const rarities = [...new Set(state.all.map((b) => b.rarity.name))]
      .sort((a, b) => (RARITY_ORDER.indexOf(a) + 99) % 99 - (RARITY_ORDER.indexOf(b) + 99) % 99);
    const classes = [...new Set(state.all.map((b) => b.class))].sort();
    buildChips('rarity-chips', rarities, 'rarity');
    buildChips('class-chips', classes, 'cls');

    $('search').addEventListener('input', (e) => { state.q = e.target.value; render(); });
    $('sort').addEventListener('change', (e) => { state.sort = e.target.value; render(); });
    $('unreleased').addEventListener('change', (e) => { state.unreleased = e.target.checked; render(); });
    $('d-close').addEventListener('click', () => $('detail').close());
    $('detail').addEventListener('click', (e) => { if (e.target === $('detail')) $('detail').close(); });
    $('detail').addEventListener('close', () => history.replaceState(null, '', location.pathname));

    render();
    openFromHash();
  }

  init();
})();
